#include <string.h>

/* ---- Expression Constructors ---- */

Expr *expr_literal_int(long long value) {
    Expr *e = calloc(1, sizeof(Expr));
    e->kind = EXPR_LITERAL;
    e->type = fl_type_i64();
    e->lit_int.ival = value;
    return e;
}

Expr *expr_literal_float(double value) {
    Expr *e = calloc(1, sizeof(Expr));
    e->kind = EXPR_LITERAL;
    e->type = fl_type_f64();
    e->lit_float.fval = value;
    return e;
}

Expr *expr_literal_string(const char *value) {
    Expr *e = calloc(1, sizeof(Expr));
    e->kind = EXPR_LITERAL;
    e->type = fl_type_string();
    e->lit_string.sval = strdup(value);
    return e;
}

Expr *expr_var(const char *name) {
    Expr *e = calloc(1, sizeof(Expr));
    e->kind = EXPR_VAR;
    e->var.name = strdup(name);
    return e;
}

Expr *expr_binary(Expr *left, Expr *right, const char *op) {
    Expr *e = calloc(1, sizeof(Expr));
    e->kind = EXPR_BINARY;
    e->binary.left = left;
    e->binary.right = right;
    e->binary.op = strdup(op);
    return e;
}

Expr *expr_unary(Expr *operand, const char *op) {
    Expr *e = calloc(1, sizeof(Expr));
    e->kind = EXPR_UNARY;
    e->unary.operand = operand;
    e->unary.op = strdup(op);
    return e;
}

Expr *expr_call(const char *func_name, Expr **args, int arg_count) {
    Expr *e = calloc(1, sizeof(Expr));
    e->kind = EXPR_CALL;
    e->call.func_name = strdup(func_name);
    e->call.arg_count = arg_count;

    /* Allocate and copy args array */
    if (arg_count > 0 && args) {
        e->call.args = malloc(sizeof(Expr *) * arg_count);
        for (int i = 0; i < arg_count; i++) {
            e->call.args[i] = args[i];
        }
    } else {
        e->call.args = NULL;
    }

    return e;
}

Expr *expr_index(Expr *array, Expr *index) {
    Expr *e = calloc(1, sizeof(Expr));
    e->kind = EXPR_INDEX;
    e->index.array = array;
    e->index.index = index;
    return e;
}

