typedef struct Expr Expr;
typedef struct Stmt Stmt;

/* ---- Expressions ---- */

typedef struct {
    long long ival;  /* int literal */
} LiteralInt;

typedef struct {
    double fval;     /* float literal */
} LiteralFloat;

typedef struct {
    const char *sval;  /* string literal */
} LiteralString;

typedef struct {
    const char *name;  /* variable name */
} VarRef;

typedef struct {
    Expr *left;
    Expr *right;
    const char *op;    /* "+", "-", "*", "/", etc */
} BinaryOp;

typedef struct {
    Expr *operand;
    const char *op;    /* "-", "!", "*", "&" */
} UnaryOp;

typedef struct {
    const char *func_name;
    Expr **args;
    int arg_count;
} FuncCall;

typedef struct {
    Expr *array;
    Expr *index;
} IndexOp;

typedef struct {
    Expr *object;
    const char *field;
} MemberOp;

typedef struct Expr {
    NodeKind kind;
    FlType *type;  /* resolved type */

    union {
        LiteralInt lit_int;
        LiteralFloat lit_float;
        LiteralString lit_string;
        VarRef var;
        BinaryOp binary;
        UnaryOp unary;
        FuncCall call;
        IndexOp index;
        MemberOp member;
    };
} Expr;

/* ---- Statements ---- */

typedef struct {
    const char *name;
    FlType *type;
    Expr *init;        /* initializer, may be NULL */
} VarDecl;

typedef struct {
    Expr *value;       /* may be NULL for void return */
} ReturnStmt;

typedef struct {
    Expr *condition;
    Stmt *then_body;
    Stmt *else_body;   /* may be NULL */
} IfStmt;

typedef struct {
    Expr *condition;
    Stmt *body;
} WhileStmt;

typedef struct {
    const char *var_name;
    Expr *start;
    Expr *end;
    Stmt *body;
} ForStmt;

typedef struct {
    Stmt **stmts;
    int count;
} BlockStmt;

/* Struct field definition */
typedef struct {
    const char *name;
    FlType *type;
} StructField;

/* Struct definition */
typedef struct {
    const char *name;
    StructField **fields;
    int field_count;
} StructDef;

typedef struct Stmt {
    NodeKind kind;

    union {
        VarDecl var_decl;
        Expr *expr;        /* for STMT_EXPR */
        ReturnStmt ret;
        IfStmt if_stmt;
        WhileStmt while_stmt;
        ForStmt for_stmt;
        BlockStmt block;
        StructDef struct_def;
    };
} Stmt;

/* ---- Functions ---- */

typedef struct {
    const char *name;
    const char **param_names;
    FlType **param_types;
    int param_count;
    FlType *return_type;
    Stmt *body;
    int is_extern;
} FuncDef;

/* ---- Program ---- */

typedef struct {
    FuncDef **functions;
    int func_count;
    const char **includes;
    int include_count;
    Stmt **struct_defs;  /* Struct definitions */
    int struct_count;
} Program;

/* ---- Constructors ---- */

Expr *expr_literal_int(long long value);
Expr *expr_literal_float(double value);
Expr *expr_literal_string(const char *value);
Expr *expr_var(const char *name);
Expr *expr_binary(Expr *left, Expr *right, const char *op);
Expr *expr_unary(Expr *operand, const char *op);
Expr *expr_call(const char *func_name, Expr **args, int arg_count);
Expr *expr_index(Expr *array, Expr *index);
Expr *expr_member(Expr *object, const char *field);

Stmt *stmt_var_decl(const char *name, FlType *type, Expr *init);
--
FuncDef *func_def_new(const char *name,
                      const char **param_names,
                      FlType **param_types,
                      int param_count,
                      FlType *return_type,
                      Stmt *body);

Program *program_new(FuncDef **funcs, int func_count);
void program_set_structs(Program *prog, Stmt **structs, int count);

/* ---- Cleanup ---- */

void expr_free(Expr *e);
void stmt_free(Stmt *s);
void func_def_free(FuncDef *f);
